    for birthdate in possible_birthdays:
        if str(date) == birthdate[1]:
            counter += 1
    if counter != 1:
        return False
    else:
        return True


def unique_month(month, possible_birthdays):
    counter = 0
    for birthdate in possible_birthdays:
        if str(month) == birthdate[0]:
            counter += 1
    if counter != 1:
        return False
    else:
        return True

def contains_unique_day(month, possible_birthdays):
    days_in_month = ()
    days_in_others = ()
    for birthdate in possible_birthdays:
        if birthdate[0] == month:
            days_in_month += (birthdate[1],)
        else:
            days_in_others += (birthdate[1],)
    for day in days_in_month:
        if day not in days_in_others:
            return True
    return False
